const test = require('node:test');
const assert = require('node:assert');
const limiter = require('../src/limiter');

test('blocks after the limit within one window', () => {
  const now = 1000;
  for (let i = 0; i < 100; i++) limiter.check('a', now);
  assert.strictEqual(limiter.check('a', now).allowed, false);
});

test('allows again in the next window', () => {
  const result = limiter.check('a', 1000 + 61000);
  assert.strictEqual(result.allowed, true);
});

